"Bei „Bohrungen“ sitzt der Kopf auf der Seite der Bohrung, die näher am Klickpunkt liegt; der Schaft zeigt in die Bohrung. Mehrere Bohrungen nacheinander anklicken, dann „Fertig“.":"“Delikler” seçildiğinde baş, deliğin tıklanan noktaya yakın tarafında yer alır; gövde deliğin içine doğru uzanır. Birkaç deliğe sırayla tıklayın, ardından “Bitti”ye basın.",
