"Den Schlüssel wie ein Kennwort behandeln: Wer ihn hat und auf diesem Rechner läuft, kann den geöffneten Entwurf ändern. Der Anschluss bleibt nur offen, solange WerkFab läuft.":"Anahtarı bir parola gibi ele alın: ona sahip olan ve bu bilgisayarda çalışan herkes açık tasarımı değiştirebilir. Bağlantı noktası yalnızca WerkFab çalıştığı sürece açık kalır.",
"Der Anschluss antwortet nicht.":"Bağlantı noktası yanıt vermiyor.",
"Der Durchmesser ist kleiner als die doppelte Wanddicke":"Çap, çift et kalınlığından küçüktür",
"Der Durchmesser würde null oder negativ – Abstand verkleinern":"Çap sıfır veya negatif olurdu – mesafeyi küçültün",
"Der Gewindefräser läuft im vollen Material: Den Zapfen vorher freifräsen (2D-Kontur außen um den Zapfen bis zur Gewindetiefe).":"Diş freze tam malzemenin içinde çalışır: Önce pimin etrafını frezeleyerek açın (pimin dışında diş derinliğine kadar 2D kontur).",
"Der Körper hat auf dieser Ebene keinen Umriss.":"Gövdenin bu düzlemde silueti yok.",
"Der Körper hat keine ebene Fläche":"Gövdenin düz yüzeyi yok",
"Der Körper ist zu dick für ein Blech":"Gövde sac için fazla kalın",
"Der Körper muss überall gleich dick sein – gezeichnet, extrudiert oder aus einer STEP-Datei. Erkannt werden die Blechdicke (Abstand der größten Fläche zu ihrer Gegenfläche), die ebenen Wände und die Biegungen dazwischen mit Winkel und Innenradius, rund oder scharfkantig. Daraus entsteht die Abwicklung; als Blech liegt sie als Skizze mit Biegelinien vor und lässt sich wie jedes Blech ändern, abwickeln und schachteln. Der K-Faktor bestimmt die gestreckten Längen. Zeigt die größte Fläche nach oben oder unten, liegt das Blech genau im Körper, sonst flach auf der XY-Ebene. Säume (180°) und gerundete Wände zwischen zwei ebenen Wänden werden als Biegung mit eigenem Radius übernommen. Nicht erkannt werden frei endende gerollte Ränder, Rohre und Umformungen wie Sicken.":"Gövde her yerde aynı kalınlıkta olmalıdır – çizilmiş, ekstrüze edilmiş veya STEP dosyasından. Sac kalınlığı (en büyük yüzeyin karşı yüzeyine uzaklığı), düz duvarlar ve aralarındaki bükümler açı ve iç yarıçapla, yuvarlak veya keskin kenarlı olarak algılanır. Bundan açınım oluşur; sac olarak büküm çizgili bir eskiz halinde bulunur ve her sac gibi değiştirilebilir, açılabilir ve yerleştirilebilir. K faktörü açınım uzunluklarını belirler. En büyük yüzey yukarı veya aşağı bakıyorsa sac tam gövdenin içinde durur, aksi halde XY düzleminde düz yatar. Kıvrımlar (180°) ve iki düz duvar arasındaki yuvarlatılmış duvarlar, kendi yarıçapıyla bir büküm olarak devralınır. Serbest uçlu yuvarlanmış kenarlar, borular ve nervür gibi şekillendirmeler algılanmaz.",
"Der Körper wird mit den Dreiecken der Anzeige als Netz übernommen. Er selbst bleibt erhalten; spätere Änderungen am Körper ändern das Netz nicht.":"Gövde, görüntüdeki üçgenlerle ağ olarak alınır. Gövdenin kendisi korunur; gövdede sonradan yapılan değişiklikler ağı değiştirmez.",
"Der Körper wird um seine senkrechte Mittelachse abgetastet und als Halterkontur (Abschnitte) in der Dokument-Werkzeugbibliothek gespeichert.":"Gövde dikey merkez ekseni etrafında taranır ve tutucu konturu (kesitler) olarak belge takım kitaplığına kaydedilir.",
"Der Nahtspalt ist größer als der Umfang":"Dikiş aralığı çevreden büyüktür",
"Der Punkt, um den sich die Ansicht dreht (bei freiem Orbit). „Unter dem Mauszeiger“: die Stelle des Modells, an der die Drehung beginnt.":"Görünümün etrafında döndüğü nokta (serbest yörüngede). „İmlecin altında“: dönmenin başladığı model noktası.",
"Der Radius wächst gleichmäßig vom Anfang zum Ende jeder gewählten Kante. Welches Ende der Anfang ist, legt die Kante fest – bei Bedarf tauschen.":"Yarıçap, seçilen her kenarın başından sonuna doğru eşit şekilde büyür. Hangi ucun başlangıç olduğunu kenar belirler – gerekirse değiştirin.",
"Der Rand einer Fläche ist eine geschlossene Kette: Mit „durchlaufend“ läuft der Radius einmal ringsum, ohne diese Option auf jeder Kante für sich vom Anfangs- zum Endradius.":"Bir yüzeyin kenarı kapalı bir zincirdir: “sürekli” ile yarıçap bir kez çevre boyunca değişir; bu seçenek olmadan her kenarda ayrı ayrı başlangıç yarıçapından bitiş yarıçapına geçer.",
"Der Schnitt trifft keinen Körper – es wird kein Material entfernt.":"Kesim hiçbir gövdeye değmiyor – malzeme kaldırılmıyor.",
"Der Text steht als Kommentar an dieser Stelle im Programm.":"Metin, programda bu noktada yorum olarak yer alır.",
"Der alte Schlüssel gilt dann nicht mehr; verbundene Agenten müssen neu eingerichtet werden":"Eski anahtar artık geçerli olmaz; bağlı ajanların yeniden ayarlanması gerekir",
"Der erste Abstand wird auf der Fläche gemessen, die mehr nach oben (Z) zeigt, der zweite Abstand bzw. der Winkel gilt zur anderen Fläche. „Seiten tauschen“ kehrt das um. Tangential anschließende Kanten laufen mit.":"Birinci mesafe, daha çok yukarı (Z) bakan yüzeyde ölçülür; ikinci mesafe veya açı diğer yüzey için geçerlidir. “Tarafları değiştir” bunu tersine çevirir. Teğet bağlanan kenarlar da dahil edilir.",
"Der gewählte Körper ist das Rohteil (z. B. ein Guss- oder Schmiederohling). Er wird selbst nicht bearbeitet.":"Seçilen gövde ham parçadır (örn. döküm veya dövme ham parça). Kendisi işlenmez.",
"Der große Geometriekern ist noch nicht geladen":"Tam geometri çekirdeği henüz yüklenmedi",
"Der große Geometriekern wird geladen – dieser Schritt rechnet gleich von selbst nach":"Büyük geometri çekirdeği yükleniyor – bu adım birazdan kendiliğinden yeniden hesaplanacak",
