"Drehen: Drehpunkt anklicken, dann den Winkel mit der Maus zeigen (Vorschau). Esc beendet.":"Döndür: dönme noktasına tıklayın, sonra açıyı fareyle gösterin (önizleme). Esc bitirir.",
"Drehen: Durchmesser, auf dem der Revolver schaltet (Okuma, LinuxCNC). 0 = Rohteil-Ø + 200 mm":"Tornalama: taret dönüşünün yapıldığı çap (Okuma, LinuxCNC). 0 = ham parça Ø + 200 mm",
"Drehen: Elemente wählen, dann Drehpunkt anklicken und den Winkel mit der Maus zeigen (Vorschau); auch als Kopie":"Döndür: öğeleri seçin, sonra dönme noktasına tıklayın ve açıyı fareyle gösterin (önizleme); kopya olarak da yapılabilir",
