"Drehen: Z vor der Planfläche, auf dem der Revolver schaltet. 0 = Sicherheitsabstand + 100 mm":"Tornalama: taret dönüşünün yapıldığı alın yüzeyi önündeki Z. 0 = güvenlik mesafesi + 100 mm",
