"Durchzug: der Rand einer runden Bohrung wird zu einem Kragen hochgezogen, etwa als Gewindedurchzug. Der Bohrungsdurchmesser der Skizze ist der fertige Innendurchmesser; im Zuschnitt wird die kleinere Vorbohrung geschnitten.":"Delik yakası: yuvarlak bir deliğin kenarı, örneğin diş için, yaka şeklinde yukarı çekilir. Eskizdeki delik çapı bitmiş iç çaptır; kesim ölçüsünde daha küçük olan ön delik kesilir.",
