"Ein eingefügter Satz verschiebt alle folgenden Satznummern – so zählen sie nicht als Änderung":"Eklenen bir blok sonraki tüm blok numaralarını kaydırır – böylece bunlar değişiklik sayılmaz",
"Ein gerollter Rand über 350° schließt sich zum Rohr – das ist so nicht herstellbar":"350° üzerindeki rulo kenar boru şeklinde kapanır – bu şekilde üretilemez",
"Ein geschlossenes Netz in einen Volumenkörper umwandeln (jedes Dreieck wird eine Fläche)":"Kapalı bir ağı katı gövdeye dönüştür (her üçgen bir yüzey olur)",
"Ein runder Fräser lässt in jeder Innenecke seinen Radius stehen – ein eckiges Gegenstück passt dann nicht hinein. Der Freistich fährt an jeder scharfen Innenecke kurz in die Ecke und zurück.{0}{1}":"Yuvarlak bir freze her iç köşede yarıçapını bırakır – köşeli bir karşı parça buna sığmaz. Boşaltma, her keskin iç köşede kısaca köşeye girip geri çıkar.{0}{1}",
"Ein verbundener Agent arbeitet am geöffneten Entwurf: Er liest und ändert die Zeitachse, fragt Körper, Volumen und Fehler ab, holt Normteile aus dem Bauteilkatalog, lässt sich ein Bild der Ansicht geben, exportiert STEP oder STL, legt Werkzeuge und Fertigungsoperationen an und gibt das NC-Programm aus – das vor dem ersten Schnitt zu prüfen bleibt. Auf Dateien, Einstellungen und andere Entwürfe hat er keinen Zugriff. Jede Änderung ist ein Schritt, den Strg+Z zurücknimmt.":"Bağlı bir ajan açık tasarım üzerinde çalışır: zaman çizelgesini okur ve değiştirir, gövdeleri, hacimleri ve hataları sorgular, standart parçaları parça kataloğundan alır, görünümün bir görüntüsünü ister, STEP veya STL olarak dışa aktarır, takımları ve imalat operasyonlarını oluşturur ve NC programını çıkarır – bu program ilk kesimden önce yine de kontrol edilmelidir. Dosyalara, tercihlere ve diğer tasarımlara erişimi yoktur. Her değişiklik, Ctrl+Z ile geri alınan tek bir adımdır.",
"Ein zweiter Klick auf die Schaltfläche des Zeichenwerkzeugs schaltet zurück auf Auswählen":"Çizim aracının düğmesine ikinci tıklama Seç aracına geri döndürür",
