"Fläche anklicken – die Bohrung entsteht mit":"Bir yüzeye tıklayın – delik birlikte oluşturulur",
"Fläche anklicken: an jedem Klickpunkt entsteht die Durchgangsbohrung für die Schraube (ISO 273, Reihe mittel) durch alle Teile, die dort aufeinanderliegen – für Senkschrauben mit 90°-Senkung, für Zylinderschrauben auf Wunsch mit Senkbohrung (DIN 974-1, Reihe 1) so tief wie der Kopf. Die Schraube sitzt gleich darin. Bohrung und Schraube lassen sich danach im Verlauf ändern.":"Bir yüzeye tıklayın: tıklanan her noktada, orada üst üste duran tüm parçalardan geçen cıvata geçiş deliği (ISO 273, orta seri) oluşturulur – havşa başlı cıvatalar için 90° havşa ile, silindirik başlı cıvatalar için isteğe bağlı olarak baş kadar derin havşa (DIN 974-1, seri 1) ile. Cıvata hemen deliğe yerleşir. Delik ve cıvata daha sonra zaman çizelgesinde değiştirilebilir.",
"Fläche eines Körpers anklicken: ihr Rand kommt als Kontur in die Skizze. Eine Kante anklicken projiziert nur diese Kante (Kreise bleiben Kreise). Projizierte Geometrie ist violett.":"Bir gövdenin yüzeyine tıklayın: kenarı kontur olarak eskize eklenir. Bir kenara tıklamak yalnızca o kenarı izdüşürür (daireler daire kalır). İzdüşürülen geometri mordur.",
