"Gemeinsame Schnittkanten: liegen zwei Zuschnitte genau eine Schnittfuge auseinander (beim Schachteln als Abstand die Schnittfuge eintragen), fällt ihre Bahn auf der gemeinsamen Kante zusammen und wird nur einmal geschnitten. Der Anschnitt liegt nie in einem Nachbarteil: ist neben einer Kontur kein freier Abfall, wird auf der Kontur eingestochen. Nach „Vorschau“ zeigt ein Bild je Tafel die Bahn, bevor die Dateien gespeichert werden.":"Ortak kesim kenarları: iki kesim parçası tam olarak bir kesim aralığı kadar uzaktaysa (yerleştirmede mesafe olarak kesim aralığını girin), yolları ortak kenarda çakışır ve yalnızca bir kez kesilir. Giriş hiçbir zaman komşu bir parçanın içinde olmaz: bir konturun yanında boş hurda yoksa delme kontur üzerinde yapılır. „Önizleme“den sonra her levha için bir görüntü, dosyalar kaydedilmeden önce yolu gösterir.",
