"Gewindebohrung im untersten Teil: die Durchgangsbohrung endet, wo das unterste Teil beginnt; dort entsteht das Kernloch mit Gewinde – drei Gewindegänge tiefer, als die Schraube reicht, oder durch das ganze Teil. Liegt nur ein Teil unter dem Punkt, bekommt es das Gewinde von der Fläche an. „Länge passend zur Einschraubtiefe“ nimmt die nächste Länge der Reihe, mit der die Schraube etwa so tief im Gewinde sitzt, wie ihr Gewinde dick ist (Richtwert für Stahl) – aber nie länger, als das Teil dick ist.":"En alttaki parçada dişli delik: geçiş deliği en alttaki parçanın başladığı yerde biter; orada dişli ön delik oluşturulur – cıvatanın eriştiğinden üç diş adımı daha derin ya da parçanın tamamından geçecek şekilde. Noktanın altında yalnızca bir parça varsa, diş yüzeyinden itibaren açılır. „Vidalama derinliğine uygun uzunluk” seçeneği, cıvatanın dişe yaklaşık diş çapı kadar derinlikte oturduğu serideki bir sonraki uzunluğu alır (çelik için kılavuz değer) – ancak asla parçanın kalınlığından uzun olmaz.",
