"Gleiche Durchmesser ergeben ein Rohr, verschiedene einen Kegelstumpf. Die Abwicklung wird auf der neutralen Faser gerechnet (Innenfläche + K-Faktor × Blechdicke); beim Runden liegt sie näher an der Blechmitte als beim Abkanten – üblich ist ein K-Faktor von 0,45 bis 0,5. Mit einer Blechregel gelten deren Dicke und K-Faktor. Der Nahtspalt bleibt am größeren Durchmesser offen (0 = stumpf gestoßen, im Körper dann ein Schlitz von 0,01 mm).":"Eşit çaplar boru, farklı çaplar kesik koni verir. Açınım nötr lifte hesaplanır (iç yüzey + K faktörü × sac kalınlığı); haddelemede sac ortasına, abkant bükmeye göre daha yakındır – genellikle 0,45 ile 0,5 arasında bir K faktörü kullanılır. Bir sac kuralı ile onun kalınlığı ve K faktörü geçerlidir. Dikiş aralığı büyük çapta açık kalır (0 = alın alına, gövdede bu durumda 0,01 mm'lik bir yarık).",
