"Heidenhain: an der Steuerung die Datenübertragung über Ethernet freigeben (wie für TNCremo, LSV2, Port 19000); Standardordner TNC 640 TNC:\\nc_prog\\, iTNC 530 TNC:\\. FTP: Port 21, Ordner z. B. /_N_WKS_DIR oder /NC. Netzwerkordner: Pfad wie \\\\MASCHINE\\NC oder Z:\\NC. DNC: Wandler als TCP-Server (raw), meist Port 4001; an der Steuerung „Abarbeiten extern“, DNC oder TAPE starten.":"Heidenhain: kontrol ünitesinde Ethernet üzerinden veri aktarımını etkinleştirin (TNCremo, LSV2 gibi, port 19000); varsayılan klasör TNC 640 TNC:\\nc_prog\\, iTNC 530 TNC:\\. FTP: port 21, klasör örn. /_N_WKS_DIR veya /NC. Ağ klasörü: yol \\\\MASCHINE\\NC veya Z:\\NC gibi. DNC: dönüştürücü TCP sunucusu (raw) olarak, genellikle port 4001; kontrol ünitesinde „Harici çalıştırma“, DNC veya TAPE başlatın.",
