"JSON kopieren":"JSON'u kopyala",
"Je Operation zwei Q-Parameter am Programmanfang: der erste verschiebt die Tiefe (DL, + = weniger tief), der zweite das seitliche Aufmaß (DR, + = mehr Aufmaß; wirkt nur bei Radiuskorrektur an der Steuerung RL/RR). An der Maschine eine Zahl ändern statt Sätze suchen.":"Program başında her operasyon için iki Q parametresi: birincisi derinliği kaydırır (DL, + = daha sığ), ikincisi yan paso payını (DR, + = daha fazla pay; yalnızca kontrol ünitesinde yarıçap düzeltmesi RL/RR ile etkili). Makinede blok aramak yerine tek bir sayıyı değiştirin.",
"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"Her eskizin ilk eğrisi – açık veya kapalı. Eğriler bir kabukla birleştirilir (kalınlığı olmayan yüzey).",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Kiemenschlitze werden auf ihrer Linie geschnitten. Haltestege: so viele Stellen je Umriss bleiben stehen (Laser, Plasma, Wasserstrahl: der Strahl setzt dort aus; Fräsen: der Fräser hebt auf halbe Blechdicke), Umrisse unter 40 mm Länge bekommen keine. „Steuerung“ legt fest, womit der Strahl ein- und ausgeschaltet wird; die Einstechzeit steht als G4 im Programm, außer die Steuerung sticht selbst ein. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"Her levha için bir dosya. Yol, dış hattın yanında hurda içinde yarım kesim aralığı kadar (frezelemede yarım freze kadar) kaydırılarak ilerler; kesikler kendi parçalarının dış hattından önce gelir, her kontur hurdadan bir girişle başlar. Panjur yarıkları kendi çizgileri üzerinde kesilir. Tutma köprüleri: dış hat başına bu kadar yer kesilmeden kalır (lazer, plazma, su jeti: ışın orada durur; frezeleme: freze sac kalınlığının yarısına kadar kalkar); 40 mm'den kısa dış hatlarda hiç köprü bırakılmaz. „Kontrol ünitesi“ ışının nasıl açılıp kapatılacağını belirler; delme süresi, kontrol ünitesi kendisi delmiyorsa programda G4 olarak yer alır. Sıfır noktası levhanın sol alt köşesidir; frezelemede Z0 sac yüzeyidir. Programı kullanmadan önce makinede veya bir NC simülatöründe kontrol edin.",
"Je Werkzeug alle Teile (weniger Werkzeugwechsel)":"Her takımla tüm parçalar (daha az takım değişimi)",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"Her eksen ayrı ayrı: bir kenara, köşeye, yüzeye veya deliğe tıklayın. Ayarlanmayan eksenler ham parça noktasından alınır.",
"Jede Bohrung wird mit ihren Koordinaten einzeln angefahren (X/Y je Bohrung) – kein Lochkreis- oder Rastermuster.":"Her delik kendi koordinatlarıyla tek tek yaklaşılır (delik başına X/Y) – delik çemberi veya ızgara deseni yok.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"Her operasyon program sonunda alt program (LBL) olarak, CALL LBL ile çağrılır",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"Eskizdeki her daire bir delik merkezidir. Delme işlemi eskiz normalinin tersi yönünde (malzemenin içine doğru) yapılır.",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"Eskizdeki her daire merkez etrafında (eskiz koordinatlarında) döndürülerek tekrarlanır – bölüm dairesi yarıçapı kadar uzaktaki bir daire, delik çemberi oluşturur.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"Eskizdeki her daire bir ızgaraya dönüşür: eskizin X ve Y yönündeki aralıkları (negatif de olabilir).",
"Jeder sichtbare Körper wird ein Glied mit Netz (STL, in Metern), Masse und Trägheit, jedes Gelenk ein Gelenk mit Achse und Grenzen. Die jetzige Stellung ist die Nullstellung. Mit einem Paketnamen stehen die Netze im URDF als package://Name/meshes/…, sonst als relativer Pfad.":"Görünen her gövde ağ (STL, metre cinsinden), kütle ve eylemsizlikle bir uzva (link), her mafsal eksen ve sınırlarla bir mafsala (joint) dönüşür. Mevcut konum sıfır konumudur. Bir paket adıyla ağlar URDF içinde package://Name/meshes/… biçiminde, aksi halde göreli yol olarak yer alır.",
"Jedes # im Skizzentext wird durch die Nummer ersetzt, mit Nullen aufgefüllt (SN-#### → SN-{0}). Bei mehreren Teilen in einer Aufspannung bekommt jedes Teil die nächste Nummer: {1}{2}.":"Eskiz metnindeki her # numarayla değiştirilir ve sıfırlarla doldurulur (SN-#### → SN-{0}). Tek bağlamada birden çok parça varsa her parça sonraki numarayı alır: {1}{2}.",
"Jedes Teil hat seinen eigenen Nullpunkt in der Steuerung (G54, G55 … bzw. Bezugspunkt-Nummer in der Tabelle – Heidenhain Zyklus 247). Alle Nullpunkte vorher an der Maschine setzen.":"Her parçanın kontrol ünitesinde kendi sıfır noktası vardır (G54, G55 … veya tablodaki referans noktası numarası – Heidenhain döngüsü 247). Tüm sıfır noktalarını önceden makinede ayarlayın.",
"Jedes eigene Maß und jeder Toleranzrahmen bekommt eine Nummer in einem Kreis. Die Liste enthält Nennmaß, Toleranz, Höchst- und Mindestmaß und Felder für den Istwert. Maße ohne eigene Toleranz bekommen die Allgemeintoleranz.":"Her ölçü ve her tolerans çerçevesi bir daire içinde numara alır. Liste anma ölçüsünü, toleransı, en büyük ve en küçük ölçüyü ve gerçek değer alanlarını içerir. Kendi toleransı olmayan ölçüler genel toleransı alır.",
"Jetzigen Stand festhalten":"Mevcut durumu kaydet",
