"KI-Agenten verbinden sich mit der Desktop-App von WerkFab (Windows, Linux, macOS) über das Model Context Protocol (MCP). Im Browser gibt es dafür keinen Anschluss.":"YZ ajanları, WerkFab masaüstü uygulamasına (Windows, Linux, macOS) Model Context Protocol (MCP) üzerinden bağlanır. Tarayıcıda bunun için bir bağlantı noktası yoktur.",
