"Kappe schieben = verschieben, drücken/ziehen = zoomen, kippen und drehen = Modell drehen. In Skizzen nur Verschieben und Zoomen. SpaceMouse Pro/Enterprise: T, F, R = Ansicht oben, vorne, rechts. Falls nichts passiert: 3Dconnexion-Treiber kurz beenden und neu verbinden.":"Kapağı kaydır = kaydır, bas/çek = yakınlaştır, eğ ve çevir = modeli döndür. Eskizlerde yalnızca kaydırma ve yakınlaştırma çalışır. SpaceMouse Pro/Enterprise: T, F, R = üst, ön, sağ görünüm. Hiçbir şey olmazsa: 3Dconnexion sürücüsünü kısa süre kapatıp yeniden bağlayın.",
