"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"Konturlar koyu alanların kenarını izler. Orta hat, çizgilerin ortasından geçer – gravürler ve çizgi çizimleri için uygundur. “Doğrular, yaylar ve daireler” düz kenarları, keskin köşeleri, yuvarlaklıkları ve daireleri algılar; “Çoklu çizgiler” görüntüyü nokta nokta izler. Ölçeği ardından gerekirse “Şablonu kalibre et” veya “Ölçekle” ile ayarlayın.",
