"Lasche an Lasche: Winkel + biegt in dieselbe Richtung weiter (U-Profil, Falz mit 180°), − in die Gegenrichtung (Z-Stufe, Hutprofil). Saum: der Rand der Lasche wird um 180° auf sich selbst zurückgelegt – offen mit einem Spalt von einer Blechdicke, geschlossen flach zugedrückt; mit − 180° liegt er auf der anderen Seite. Das Feld R ist der Innenradius nur dieser Biegung (leer = wie beim Blech). Für einen Saum direkt an der Plattenkante die Lasche selbst auf 180° stellen. Kröpfung: zwei Biegungen gegeneinander (− 45° und + 45°) – der Rand läuft parallel versetzt weiter; Versatz über die Länge des schrägen Stücks und die Winkel.":"Kanat üzerine kanat: + açısı aynı yönde bükmeye devam eder (U profil, 180° kenet), − ters yönde (Z kademe, şapka profil). Kıvrım: kanadın kenarı kendi üzerine 180° katlanır – açıkta bir sac kalınlığı kadar boşlukla, kapalıda düz bastırılarak; − 180° ile diğer tarafta durur. R alanı yalnızca bu bükümün iç yarıçapıdır (boş = sactaki gibi). Doğrudan plaka kenarında bir kıvrım için kanadın kendisini 180° yapın. Basamak: birbirine ters iki büküm (− 45° ve + 45°) – kenar paralel ve kaymış olarak devam eder; kayma, eğik parçanın uzunluğundan ve açılardan çıkar.",
"Lasche {0}":"Flanş {0}",
