"Macht ein geschlossenes Netz hohl: eine Innenwand im Abstand der Wandstärke kommt dazu – spart Material und Druckzeit. Stellen, die dünner sind als zwei Wandstärken, überschneiden sich danach; für Harzdruck ein Ablaufloch mit „Boolesch“ abziehen.":"Kapalı bir ağın içini boşaltır: et kalınlığı mesafesinde bir iç duvar eklenir – malzemeden ve baskı süresinden tasarruf sağlar. İki et kalınlığından ince yerler sonrasında kesişir; reçine baskısı için „Boole“ ile bir tahliye deliği çıkarın.",
