"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"Birbirine bağlı birden çok kenar tek bir yol sayılır: yarıçap zincirin başından sonuna kadar değişir, kontrol noktaları tüm zincir uzunluğunun % değeri olarak verilir. Bunu büyük geometri çekirdeği hesaplar.",
"Mehrfachaufspannung":"Çoklu parça",
"Mehrfachaufspannung: Nullpunkt von Teil {0} gibt es an dieser Steuerung nicht – nur ein Teil ausgegeben":"Çoklu parça: bu kontrol ünitesinde parça {0} için sıfır noktası yok – yalnızca bir parça çıktı",
"Mehrfachaufspannung: Nullpunktverschiebung gibt es in diesem Postprozessor nicht – „Eigener Nullpunkt je Teil“ wählen; nur ein Teil ausgegeben":"Çoklu parça: bu post işlemcide sıfır noktası kaydırma yok – “Her parça için ayrı sıfır noktası” seçin; yalnızca bir parça çıktı",
"Meine Designs · {0}":"Tasarımlarım · {0}",
"Meine Werkzeuge":"Takımlarım",
"Meldet Bahnen, die tiefer schneiden als das Modell an dieser Stelle (Schaft-, Plan-, Kugel- und Torusfräser, Fasenfräser und Bohrer mit ihrem Kegel; 3-Achs-Bewegungen). Ein Schnitt, der nicht im Modell steht – Gravur, Eckenfreistich, Tasche nur aus einer Skizze – wird ebenfalls gemeldet.":"Bu noktada modelden daha derin kesen takım yollarını bildirir (parmak, yüzey, küresel ve torus frezeler, pah frezeleri ve konileriyle matkaplar; 3 eksenli hareketler). Modelde olmayan bir kesim – gravür, köşe boşluğu, yalnızca bir eskizden oluşturulan cep – de bildirilir.",
"Meldung auf dem Bildschirm der Steuerung: Fanuc und LinuxCNC als (MSG, …), Sinumerik als MSG(\"…\"), sonst als Kommentar.":"Kontrol ekranında mesaj: Fanuc ve LinuxCNC için (MSG, …), Sinumerik için MSG(\"…\"), diğerlerinde yorum olarak.",
