"Verrechnet zwei geschlossene Netze wirklich miteinander: innen liegende Flächen verschwinden, die Schnittkanten werden neu vernetzt. Gerechnet wird nur dort, wo sich die beiden Netze begegnen können – ein großes Netz mit einem kleinen Eingriff geht deshalb schnell. Überlappen zwei große Netze ganz, vorher „Reduzieren“.":"İki kapalı ağı gerçekten birbirine işler: içte kalan yüzeyler kaybolur, kesişim kenarları yeniden ağlanır. Hesaplama yalnızca iki ağın karşılaşabileceği bölgede yapılır – bu yüzden büyük bir ağda küçük bir işlem hızlıdır. İki büyük ağ tamamen çakışıyorsa önce „Azalt“ kullanın.",
