"Verschraubung: Scheiben und Mutter kommen mit der Schraube in einem Zug an jede angeklickte Bohrung. Die Klemmdicke ist die Länge der Bohrung – durch mehrere Teile hindurch, wenn ihre Bohrungen fluchten und aneinanderstoßen. Mit Mutter wird die kürzeste Vorzugslänge vorgeschlagen, bei der die Schraube zwei Gewindegänge aus der Mutter ragt.":"Cıvata bağlantısı: rondelalar ve somun, cıvatayla birlikte tek seferde tıklanan her deliğe yerleştirilir. Sıkıştırma kalınlığı deliğin uzunluğudur – delikleri hizalı ve birbirine bitişikse birden çok parça boyunca. Somunla birlikte, cıvatanın somundan iki diş adımı kadar çıktığı en kısa tercih edilen uzunluk önerilir.",
