"Wickelt die Skizzenkurven auf den Zylinder: X bleibt X, der Abstand quer zur Achse wird zum Bogen auf dem Abwicklungs-Ø (Drehung A). Die Skizze muss parallel zur A-Achse liegen, z. B. auf einer Tangentialebene. Gefräst wird in fester Tiefe unter der Teiloberfläche – für Gravuren, Schriften und Nuten rund um das Teil.":"Eskiz eğrilerini silindire sarar: X, X olarak kalır; eksene dik mesafe açınım Ø üzerinde bir yaya dönüşür (A dönüşü). Eskiz A eksenine paralel olmalıdır, örn. bir teğet düzlemde. Parça yüzeyinin altında sabit derinlikte frezelenir – parça çevresinde gravür, yazı ve kanallar için.",
"Wie 3D-Kontur, aber das Werkzeug fährt ohne Absätze kontinuierlich nach unten – keine Eintauchmarken an steilen Wänden.":"3B kontur gibi, ancak takım kademesiz ve sürekli aşağı iner – dik duvarlarda dalma izi kalmaz.",
