"Wie fein Zylinder, Kugeln und Rundungen in der Ansicht aus Dreiecken bestehen. Feiner sieht runder aus, rechnet bei großen Modellen aber länger. Der Export hat eine eigene Einstellung (3D-Druck).":"Silindirlerin, kürelerin ve yuvarlatmaların görünümde ne kadar ince üçgenlerden oluştuğu. Daha ince daha yuvarlak görünür, ancak büyük modellerde hesaplama daha uzun sürer. Dışa aktarmanın kendi ayarı vardır (3D baskı).",
