"Zungen stehen am freien Ende der Lasche über und kommen in den Zuschnitt. „Schlitze als Skizze“ legt die passenden Schlitze dort an, wo die Zungen stehen – je Ebene eine Skizze, jeder Schlitz ringsum um das Spiel größer als die Zunge. In dieser Skizze den Umriss des Gegenstücks zeichnen und daraus ein Blech oder eine Extrusion machen: die Schlitze werden Ausschnitte. Das Gegenstück liegt auf den Laschenenden auf; die Zungenlänge ist üblich gleich seiner Dicke.":"Diller kanadın serbest ucunda dışarı taşar ve kesim ölçüsüne dahil olur. “Kanallar eskiz olarak” dillerin bulunduğu yerlere uygun kanalları oluşturur – her düzleme bir eskiz, her kanal dilden etrafında boşluk kadar büyüktür. Bu eskizde karşı parçanın dış hattını çizin ve bundan bir sac veya ekstrüzyon oluşturun: kanallar kesikler olur. Karşı parça kanat uçlarına oturur; dil uzunluğu genellikle onun kalınlığına eşittir.",
